// Simple deployment orchestrator server
const http = require('http');
const url = require('url');

// Create server
const server = http.createServer((req, res) => {
  const parsedUrl = url.parse(req.url, true);

  // Handle POST requests to /api/deploy-config
  if (req.method === 'POST' && parsedUrl.pathname === '/api/deploy-config') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const config = JSON.parse(body);
        console.log('\nReceived deployment configuration:');

        // Display configuration with sensitive values redacted
        Object.keys(config).forEach(key => {
          let value = config[key];
          if (key.includes('SECRET') || key.includes('KEY') || key.includes('TOKEN')) {
            value = value.substring(0, 5) + '[REDACTED]' + value.slice(-2);
          }
          console.log(`  ${key}: ${value}`);
        });

        // Send success response
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          status: 'success', 
          message: 'Configuration received' 
        }));
      } catch (error) {
        console.error('Error processing request:', error);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          status: 'error', 
          message: 'Invalid JSON' 
        }));
      }
    });
  }
  // Handle GET requests to /api/deploy-config
  else if (req.method === 'GET' && parsedUrl.pathname === '/api/deploy-config') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ 
      status: 'alive', 
      service: 'deployment-orchestrator' 
    }));
  }
  // Handle all other routes
  else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ 
      status: 'error', 
      message: 'Not found' 
    }));
  }
});

// Start server on port 3003
const PORT = 3003;
server.listen(PORT, 'localhost', () => {
  console.log(`Deployment orchestrator running on http://localhost:${PORT}`);
});

// Handle server errors
server.on('error', (error) => {
  console.error('Server error:', error);
});

